def check_n(n):
    # We need to find if there exists S in (-1, 1) such that
    # Q = 20 - S^2 satisfies Q_min(S) <= Q <= Q_max(S)
    # Q_min(S) = S^2 / n
    # Q_max(S) = n-1 + (S-j)^2 where j is an integer such that
    # j <= n-1, j has the same parity as n-1, and |S-j| <= 1.

    # Let's use a denser sampling of S.
    for i in range(-1000, 1001):
        S_val = i / 1000
        if S_val == 0: continue
        Q = 20 - S_val**2
        if Q < 0: continue

        q_min = S_val**2 / n

        q_max = -1
        for j in range(-(n-1), n):
            if (j % 2) == ((n-1) % 2):
                if S_val - 1 <= j <= S_val + 1:
                    q_max = max(q_max, (n-1) + (S_val - j)**2)

        if q_min <= Q <= q_max:
            # We need Q < q_max to ensure x_i in (-1, 1)
            if Q < q_max:
                return True
    return False

for n in range(1, 30):
    if check_n(n):
        print(f"Found n = {n}")
        break
